import re

def cmp_semver(a, b):
    def parse(version):
        # Remove build metadata
        main_part = version.split('+')[0]
        # Split into main version and pre-release
        parts = main_part.split('-')
        main_version_str = parts[0]
        pre_release_str = parts[1] if len(parts) > 1 else None

        # Parse major.minor.patch
        main_parts = [int(x) for x in main_version_str.split('.')]
        # Ensure we have 3 parts even if missing
        while len(main_parts) < 3:
            main_parts.append(0)

        pre_release = []
        if pre_release_str is not None:
            for item in pre_release_str.split('.'):
                if item.isdigit():
                    pre_release.append((0, int(item))) # 0 for numeric
                else:
                    pre_release.append((1, item)) # 1 for alphanumeric

        return main_parts, pre_release

    main_a, pre_a = parse(a)
    main_b, pre_b = parse(b)

    # Compare major.minor.patch
    if main_a > main_b:
        return 1
    if main_a < main_b:
        return -1

    # Pre-release logic
    # A version WITH a pre-release sorts BEFORE the same version WITHOUT one
    if pre_a and not pre_b:
        return -1
    if not pre_a and pre_b:
        return 1
    if not pre_a and not pre_b:
        return 0

    # Compare pre-release identifiers
    for i in range(max(len(pre_a), len(pre_b))):
        if i >= len(pre_a):
            return -1
        if i >= len(pre_b):
            return 1

        type_a, val_a = pre_a[i]
        type_b, val_b = pre_b[i]

        if type_a != type_b:
            return -1 if type_a < type_b else 1

        if val_a != val_b:
            return -1 if val_a < val_b else 1

    return 0
