import re

def parse_range(header, size):
    if not header or 'bytes=' not in header:
        return None

    try:
        # Extract the part after 'bytes='
        range_part = header.split('bytes=')[-1].strip()
        # Split by comma and clean whitespace
        raw_ranges = [r.strip() for r in range_part.split(',')]
    except (IndexError, AttributeError):
        return None

    results = []

    for r in raw_ranges:
        if not r:
            continue

        try:
            if '-' in r:
                parts = r.split('-')
                start_str = parts[0].strip()
                end_str = parts[1].strip() if len(parts) > 1 else ""

                # Handle suffix (e.g., -500)
                if start_str.startswith('-'):
                    suffix_len = int(start_str[1:])
                    start = max(0, size - suffix_len)
                    end = size - 1
                else:
                    start = int(start_str)
                    if end_str == "":
                        end = size - 1
                    else:
                        end = int(end_str)
            else:
                # Single value (e.g., 500)
                start = int(r)
                end = start

            # Clamp end to size
            end = min(end, size - 1)

            # Check satisfiability
            if start >= size or start > end:
                continue

            # Ensure start is not negative (for suffix logic)
            start = max(0, start)

            results.append((start, end))
        except ValueError:
            return None

    if not results:
        return None

    return results
```

