def to_base(n, alphabet):
    if n == 0:
        return alphabet[0]

    is_negative = n < 0
    n = abs(n)
    base = len(alphabet)

    digits = []
    while n > 0:
        digits.append(alphabet[n % base])
        n //= base

    res = "".join(reversed(digits))
    return "-" + res if is_negative else res

def from_base(s, alphabet):
    if not s:
        raise ValueError("Empty string")

    is_negative = False
    if s.startswith('-'):
        is_negative = True
        s = s[1:]

    base = len(alphabet)
    char_to_int = {char: i for i, char in enumerate(alphabet)}

    result = 0
    for char in s:
        if char not in char_to_int:
            raise ValueError(f"Character {char} not in alphabet")
        result = result * base + char_to_int[char]

    return -result if is_negative else result
```

