import heapq

def topo_lex(graph):
    in_degree = {}
    all_nodes = set(graph.keys())
    for successors in graph.values():
        for node in successors:
            all_nodes.add(node)

    for node in all_nodes:
        in_degree[node] = 0

    for u in graph:
        for v in graph[u]:
            in_degree[v] += 1

    heap = [node for node in all_nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)

        if u in graph:
            for v in graph[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    heapq.heappush(heap, v)

    if len(result) == len(all_nodes):
        return result
    else:
        return None
```

