import re

class Spreadsheet:
    def __init__(self):
        self.cells = {}  # cell_id -> value (int or str)
        self.cache = {}  # cell_id -> computed_value
        self.dependencies = {}  # cell_id -> set of cell_ids it depends on
        self.reverse_deps = {}  # cell_id -> set of cell_ids that depend on it

    def _parse_formula(self, formula):
        if not formula.startswith('='):
            return None
        expr = formula[1:]
        # Tokenize: numbers, cell refs (A1, B10), and operators (+, -, *)
        tokens = re.findall(r'[A-Z]+\d+|[0-9]+|[\+\-\*]', expr)

        # Convert tokens to internal representation
        parsed_tokens = []
        for t in tokens:
            if t.isdigit():
                parsed_tokens.append(('num', int(t)))
            elif re.match(r'[A-Z]+\d+', t):
                parsed_tokens.append(('ref', t))
            else:
                parsed_tokens.append(('op', t))
        return parsed_tokens

    def _get_cell_id(self, cell):
        if not isinstance(cell, str) or not cell[0].isalpha():
            return cell
        return cell

    def set(self, cell, value):
        cell_id = self._get_cell_id(cell)

        # Check for cycles
        new_deps = set()
        if isinstance(value, str) and value.startswith('='):
            tokens = self._parse_formula(value)
            if tokens:
                for t, _ in tokens:
                    if t == 'ref':
                        new_deps.add(t)

        # Cycle detection using DFS
        visited = set()
        def has_cycle(curr, target_deps):
            if curr in target_deps: return True
            if curr in visited: return False
            visited.add(curr)
            for dep in self.dependencies.get(curr, set()):
                if has_cycle(dep, target_deps): return True
            return False

        # Temporary check
        temp_deps = new_deps
        if any(has_cycle(d, temp_deps) for d in new_deps):
            raise ValueError("Cycle detected")

        # Commit changes
        self.cells[cell_id] = value
        self.dependencies[cell_id] = new_deps

        # Update reverse dependencies
        for dep in new_deps:
            if dep not in self.reverse_deps:
                self.reverse_deps[dep] = set()
            self.reverse_deps[dep].add(cell_id)

        # Invalidate cache for this cell and all downstream
        self._invalidate_cache(cell_id)

    def _invalidate_cache(self, cell_id):
        if cell_id in self.cache:
            del self.cache[cell_id]
            for downstream in self.reverse_deps.get(cell_id, set()):
                self._invalidate_cache(downstream)

    def get(self, cell):
        cell_id = self._get_cell_id(cell)
        if cell_id in self.cache:
            return self.cache[cell_id]

        val = self.cells.get(cell_id, 0)
        if not isinstance(val, str) or not val.startswith('='):
            res = val if isinstance(val, int) else 0
            self.cache[cell_id] = res
            return res

        # Evaluate formula
        tokens = self._parse_formula(val)
        if not tokens:
            res = 0
        else:
            # Standard Shunting-yard or simple recursive descent for + - *
            # Since we need O(1) amortized, we compute and cache
            def evaluate(ts):
                # Handle * first
                stack = []
                i = 0
                while i < len(ts):
                    t = ts[i]
                    if t[0] == 'num': stack.append(t[1])
                    elif t[0] == 'ref': stack.append(self.get(t[1]))
                    elif t[0] == 'op':
                        if t[1] == '*':
                            right = stack.pop()
                            left = stack.pop()
                            stack.append(left * right)
                        else:
                            stack.append(t[1])
                    i += 1

                # Handle + and -
                res = stack[0]
                i = 1
                while i < len(stack):
                    op = stack[i]
                    right = stack[i+1]
                    if op == '+': res += right
                    elif op == '-': res -= right
                    i += 2
                return res

            res = evaluate(tokens)

        self.cache[cell_id] = res
        return res
